// 기존 fullintent rollback미확인 fixture는 port의 가정이다. 아래는 실 AccessRepository 자체의 release 호출 관측이다.
import {AccessRepository as RealAccessRepository} from '../../../apps/server/modules/access/repository.ts';
function realAccessPool(){
 const sqls:string[]=[],unexpected:string[]=[],releaseArgs:unknown[]=[],connections:number[]=[];let sequence=0,current:any=null,fault='';
 const bodyError=Error('synthetic-body-failure'),rollbackError=Object.assign(Error('synthetic-rollback-connection-unknown'),{code:'ECONNRESET'}),commitError=Object.assign(Error('synthetic-commit-ack-unknown'),{code:'ECONNRESET'});let committed=0;
 const makeClient=()=>{const client={id:++sequence,destroyed:false,async query(sql:string,args:any[]=[]){sqls.push(sql);
  if(sql==='BEGIN')return{rows:[]};
  if(sql==='COMMIT'){const mode=fault;fault='';if(mode==='COMMIT_BEFORE')throw commitError;committed++;if(mode==='COMMIT_AFTER')throw commitError;return{rows:[]};}
  if(sql==='ROLLBACK'){if(fault==='ROLLBACK'){fault='';throw rollbackError;}return{rows:[]};}
  if(sql.startsWith('SELECT s.*,u.id AS uid,')&&sql.includes('FROM anvil.auth_sessions s JOIN anvil.users u')&&sql.endsWith('FOR UPDATE OF u,s,c')){assert.deepEqual(args,[contentHash(intentToken)]);return{rows:[{id:sessionId,uid:actorId,client_id:clientId,display_name:'합성 인증주체',normalized_login_name:'synthetic-user',server_owner:false,user_status:'ACTIVE',user_revoked_at:null,client_revoked_at:null,revoked_at:null,credential_generation:1,current_generation:1,csrf_digest:contentHash(intentCsrf),idle_expires_at:new Date('2099-01-01T00:00:00.000Z'),absolute_expires_at:new Date('2099-01-01T00:00:00.000Z'),reauth_until:null}]};}
  if(sql==='SELECT 1 AS ok')return{rows:[{ok:1}]};
  unexpected.push(sql);throw Error('UNEXPECTED_REAL_ACCESS_SQL');
 },release(error?:unknown){releaseArgs.push(error);if(error instanceof Error)client.destroyed=true;}};return client;};
 const pool={async connect(){if(!current||current.destroyed)current=makeClient();connections.push(current.id);return current;}};
 const repository=new RealAccessRepository(pool as any,{installationId:'77777777-7777-4777-8777-777777777777',key:Buffer.alloc(32,0x55)});
 const run=(failBody=false)=>repository.authenticated(intentToken,intentCsrf,async(db,a)=>{assert.equal(a.actorId,actorId);assert.equal(a.clientId,clientId);assert.equal(a.authSession!.id,sessionId);assert.equal((await db.query('SELECT 1 AS ok')).rows[0].ok,1);if(failBody)throw bodyError;return 'CONFIRMED';});
 return{run,sqls,unexpected,releaseArgs,connections,bodyError,rollbackError,commitError,fault:(mode:string)=>{fault=mode;},committed:()=>committed};
}

test('realAccess 정상COMMIT은연결을정상반환하고검증된같은client재사용을유지한다',async()=>{const f=realAccessPool();assert.equal(await f.run(),'CONFIRMED');assert.equal(await f.run(),'CONFIRMED');assert.deepEqual(f.releaseArgs,[undefined,undefined]);assert.equal(f.connections[0],f.connections[1]);assert.equal(f.committed(),2);assert.equal(f.sqls.filter(s=>s==='COMMIT').length,2);assert.deepEqual(f.unexpected,[]);});
test('realAccess 확정ROLLBACK은원오류를유지하고연결을정상반환한다',async()=>{const f=realAccessPool();await assert.rejects(f.run(true),e=>e===f.bodyError);assert.equal(await f.run(),'CONFIRMED');assert.deepEqual(f.releaseArgs,[undefined,undefined]);assert.equal(f.connections[0],f.connections[1]);assert.equal(f.sqls.filter(s=>s==='ROLLBACK').length,1);assert.deepEqual(f.unexpected,[]);});
test('realAccess ROLLBACK실패는원업무오류를유지하면서불명연결을error로폐기한다',async()=>{const f=realAccessPool();f.fault('ROLLBACK');await assert.rejects(f.run(true),e=>e===f.bodyError);assert.equal(await f.run(),'CONFIRMED');assert.strictEqual(f.releaseArgs[0],f.rollbackError,'실 release(error) 없이는 fakePool이 연결을 폐기하지 않는다');assert.notEqual(f.connections[0],f.connections[1],'제품이 폐기하지 않은 연결을 mock이 자동 폐기하지 않는다');assert.equal(f.sqls.filter(s=>s==='ROLLBACK').length,1);assert.deepEqual(f.unexpected,[]);});
for(const point of ['COMMIT_BEFORE','COMMIT_AFTER'])test('realAccess '+point+' 응답불명은성공값0·원commit오류·연결폐기를보존한다',async()=>{const f=realAccessPool();f.fault(point);await assert.rejects(f.run(),e=>e===f.commitError);assert.equal(f.committed(),point==='COMMIT_BEFORE'?0:1);assert.equal(await f.run(),'CONFIRMED');assert.strictEqual(f.releaseArgs[0],f.commitError);assert.notEqual(f.connections[0],f.connections[1]);assert.deepEqual(f.unexpected,[]);});

