import {ProjectApprovals as FulfillApprovalClass} from '../../../apps/server/modules/approvals/project-approvals.ts';
const targetPost=(f:Awaited<ReturnType<typeof intentFixture>>,ref:any,app=f.app)=>app.inject({method:'POST',url:'/api/v1/projects/'+f.command.projectId+'/backup-resource-intents/'+ref.id+'/fulfill',headers:{host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken,origin:intentOrigin,'x-anvil-csrf':intentCsrf},payload:{intentRef:ref,secretInput:null}});
const targetGet=(f:Awaited<ReturnType<typeof intentFixture>>,suffix:string,app=f.app)=>app.inject({method:'GET',url:'/api/v1/projects/'+f.command.projectId+suffix,headers:{host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken}});
function targetView(response:any,ref:any,state:string){assert.equal(response.statusCode,200,response.body);const v=response.json();assert.deepEqual(Object.keys(v).sort(),['intentRef','action','resourceRef','state','expiresAt','resultRef','reasonCodes'].sort());assert.deepEqual(v.intentRef,ref);assert.equal(v.action,'REGISTER_TARGET');assert.equal(v.resourceRef,null);assert.equal(v.state,state);assert(Array.isArray(v.reasonCodes));assert(!JSON.stringify(v).includes('/synthetic/'));return v;}
async function waitForProbe(f:Awaited<ReturnType<typeof intentFixture>>,running:Promise<any>){f.probe.entered??=new Promise<void>(resolve=>{f.probe.markEntered=resolve;});const first=await Promise.race([f.probe.entered.then(()=>({kind:'PROBE',body:''})),running.then(r=>({kind:'EARLY',body:r.body}))]);assert.equal(first.kind,'PROBE',first.body);}
function armProbe(f:Awaited<ReturnType<typeof intentFixture>>){f.probe.paused=true;f.probe.entered=new Promise<void>(resolve=>{f.probe.markEntered=resolve;});}

test('targetFulfill 원CONSUMED의durableclaim뒤probe하고descriptor/R2목록·고정조회까지연결한다',async()=>{const f=await intentFixture();const originalAuthorize=FulfillApprovalClass.prototype.authorize,originalConsume=FulfillApprovalClass.prototype.consume;let authorizeCalls=0,consumeCalls=0;try{const ref=intentOk(await f.post(f.command)).data.intentRef;const sourceResult=structuredClone(f.tables.commands[0].result_ref);FulfillApprovalClass.prototype.authorize=async()=>{authorizeCalls++;throw Error('FULFILL_REAUTHORIZE_FORBIDDEN');};FulfillApprovalClass.prototype.consume=async()=>{consumeCalls++;throw Error('FULFILL_RECONSUME_FORBIDDEN');};const done=targetView(await targetPost(f,ref),ref,'SUCCEEDED');assert.equal(authorizeCalls,0);assert.equal(consumeCalls,0);assert(done.resultRef&&done.resultRef.version===1);assert.equal(f.tables.commands.length,1);assert.equal(f.tables.receipts.length,1);assert.equal(f.tables.audits.length,1);assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.tables.commands[0].result_ref,sourceResult,'원INTENT_READY receipt불변');assert.equal(f.resources.heads.length,1);assert.equal(f.resources.versions.length,1);assert(f.resources.events.length>=1);const descriptor=f.resources.versions[0];assert.equal(descriptor.origin_intent_id,ref.id);assert.equal(descriptor.command_id,f.tables.commands[0].id);assert.equal(descriptor.content_hash,done.resultRef.contentHash);assert(descriptor.snapshot_json);assert.equal(intentHash(descriptor.snapshot_json),done.resultRef.contentHash);assert.equal(descriptor.snapshot_json.kind,'TARGET');assert.equal(descriptor.snapshot_json.displayName,f.payload.displayName);assert.deepEqual(f.probe.trace.filter(v=>v==='CREATE'),['CREATE']);for(const event of ['ROOT','SYNC','READ','STAT','REMOVE','PARENT_SYNC'])assert(f.probe.trace.includes(event),event);assert.equal(f.probe.files.size,0);const read=targetView(await targetGet(f,'/backup-resource-intents/'+ref.id),ref,'SUCCEEDED');assert.deepEqual(read.resultRef,done.resultRef);const listResponse=await targetGet(f,'/backup-resources?kind=TARGET&limit=50');assert.equal(listResponse.statusCode,200,listResponse.body);const list=listResponse.json();assert.equal(list.state,'CONFIGURED');assert.equal(list.page.items.length,1);const item=list.page.items[0];assert.deepEqual(item.ref,done.resultRef);assert.equal(item.kind,'TARGET');assert.equal(item.displayName,f.payload.displayName);assert.equal(item.current.eligible,true);assert.deepEqual(item.current.reasonCodes,[]);assert.match(item.providerProfileRef.contentHash,/^[a-f0-9]{64}$/);assert.match(item.protectionEvidenceRef.contentHash,/^[a-f0-9]{64}$/);const fixed=await targetGet(f,'/backup-resources/'+done.resultRef.id+'/versions/1');assert.equal(fixed.statusCode,200,fixed.body);assert.deepEqual(fixed.json().ref,done.resultRef);assert.equal(fixed.json().current.eligible,true);assert(!JSON.stringify([list,fixed.json()]).includes('/synthetic/'));const counts={commands:f.tables.commands.length,receipts:f.tables.receipts.length,audits:f.tables.audits.length,consumed:f.tables.consumptions.length,heads:f.resources.heads.length,versions:f.resources.versions.length,events:f.resources.events.length,probe:f.probe.trace.length};assert.deepEqual(targetView(await targetPost(f,ref),ref,'SUCCEEDED'),done);assert.deepEqual({commands:f.tables.commands.length,receipts:f.tables.receipts.length,audits:f.tables.audits.length,consumed:f.tables.consumptions.length,heads:f.resources.heads.length,versions:f.resources.versions.length,events:f.resources.events.length,probe:f.probe.trace.length},counts,'동일fulfill 재제출의probe/descriptor/event/승인추가0');assert.deepEqual(f.unexpected,[]);}finally{FulfillApprovalClass.prototype.authorize=originalAuthorize;FulfillApprovalClass.prototype.consume=originalConsume;await f.close();}});

test('targetFulfill 동시재제출은실PROCESSING을보고409이며원probe는단1회다',{timeout:5000},async()=>{const f=await intentFixture();let running:Promise<any>|undefined;try{const ref=intentOk(await f.post(f.command)).data.intentRef;armProbe(f);running=targetPost(f,ref);await waitForProbe(f,running);assert.equal(f.tables.intents[0].state,'PROCESSING');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);intentError(await targetPost(f,ref),409,'RESOURCE_PROCESSING');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);f.probe.release!();targetView(await running,ref,'SUCCEEDED');assert.equal(f.resources.versions.length,1);assert.equal(f.tables.consumptions.length,1);}finally{f.probe.release?.();if(running)await running.catch(()=>{});await f.close();}});

test('targetFulfill 원command/consumedreceipt 단독변조는claim·probe전에503으로닫힌다',async()=>{for(const field of ['commandHash','receiptDigest','consumptionDigest']){const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;if(field==='commandHash')f.tables.commands[0].request_hash='0'.repeat(64);if(field==='receiptDigest')f.tables.receipts[0].scope_digest='0'.repeat(64);if(field==='consumptionDigest')f.tables.consumptions[0].scope_digest='0'.repeat(64);intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.io(),0);assert.equal(f.probe.trace.length,0);assert.equal(f.resources.versions.length,0);assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}}});

test('targetFulfill probe뒤최종control/원최단기한변경은descriptor성공0·같은intent재실행0이다',async()=>{for(const change of ['control','expiry']){const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;f.probe.afterProbe=()=>{if(change==='control')f.current.generation=2;else f.clock(new Date(Date.parse(f.at)+46000).toISOString());};intentError(await targetPost(f,ref),change==='control'?409:412,change==='control'?'CONTROL_GENERATION_CONFLICT':'RESOURCE_UNVERIFIED');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.equal(f.resources.versions.length,0);assert.notEqual(f.tables.intents[0].state,'READY');assert.notEqual(f.tables.intents[0].state,'SUCCEEDED');const count=f.probe.trace.length;await targetPost(f,ref);assert.equal(f.probe.trace.length,count);assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}}});

test('targetFulfill root보호/실readback불일치는단순verified true로성공시키지않는다',async()=>{for(const bad of ['mode','readback']){const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;if(bad==='mode')f.probe.rootMode='755';else f.probe.readMismatch=true;intentError(await targetPost(f,ref),412,'RESOURCE_UNVERIFIED');assert(f.probe.trace.includes('ROOT'));if(bad==='mode')assert.equal(f.probe.trace.includes('CREATE'),false);else assert(f.probe.trace.includes('READ'));assert.equal(f.resources.versions.length,0);assert.notEqual(f.tables.intents[0].state,'READY');assert.equal(f.tables.consumptions.length,1);}finally{await f.close();}}});

test('targetFulfill probe뒤DB저장/COMMIT응답불명은UNKNOWN·자료보존·GET만허용하고자동복구0이다',async()=>{for(const fault of ['RESOURCE','RESOURCE_COMMIT_AFTER']){const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;f.fault.mode=fault;intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.fault.hits,1,'실제fault도달');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.equal(f.tables.intents[0].state,'UNKNOWN');if(fault==='RESOURCE_COMMIT_AFTER')assert.equal(f.resources.versions.length,1,'성공했을수있는descriptor삭제0');else assert.equal(f.resources.versions.length,0);f.fault.mode='';const before=f.probe.trace.length;const view=targetView(await targetGet(f,'/backup-resource-intents/'+ref.id),ref,'UNKNOWN');assert.equal(view.resultRef,null);intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.probe.trace.length,before);assert.equal(f.tables.intents[0].state,'UNKNOWN');assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}}});

test('targetFulfill cold인스턴스는이전PROCESSING을UNKNOWN으로조회하고probe를재개하지않는다',{timeout:5000},async()=>{const f=await intentFixture();let running:Promise<any>|undefined,cold:ReturnType<typeof buildApp>|undefined;try{const ref=intentOk(await f.post(f.command)).data.intentRef;armProbe(f);running=targetPost(f,ref);await waitForProbe(f,running);assert.equal(f.tables.intents[0].state,'PROCESSING');cold=buildApp({},undefined,{repository:f.access,origin:intentOrigin});const before=f.probe.trace.length;targetView(await targetGet(f,'/backup-resource-intents/'+ref.id,cold),ref,'UNKNOWN');intentError(await targetPost(f,ref,cold),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.probe.trace.length,before);assert.equal(f.tables.intents[0].state,'UNKNOWN');f.probe.release!();intentError(await running,503,'RESOURCE_STATE_UNKNOWN');targetView(await targetGet(f,'/backup-resource-intents/'+ref.id,cold),ref,'UNKNOWN');assert.equal(f.tables.intents[0].state,'UNKNOWN');assert.equal(f.resources.versions.length,0,'늦은옛claim이descriptor성공으로UNKNOWN을덮지못한다');assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.unexpected,[]);}finally{f.probe.release?.();if(running)await running.catch(()=>{});if(cold)await cold.close();await f.close();}});

for(const mode of ['query','csrf','connector','body-limit'] as const)test('targetBoundary '+mode+'는claim/probe0·no-store로닫힌다',async()=>{const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef,headers:Record<string,string>={host:'localhost:3830',cookie:'__Host-anvil.sid='+intentToken,origin:intentOrigin,'x-anvil-csrf':intentCsrf};if(mode==='csrf')delete headers['x-anvil-csrf'];if(mode==='connector')headers.authorization='Bearer av3ct1_'+'t'.repeat(43);const payload=mode==='body-limit'?{intentRef:ref,secretInput:null,padding:'x'.repeat(21000)}:{intentRef:ref,secretInput:null};const r=await f.app.inject({method:'POST',url:'/api/v1/projects/'+pid+'/backup-resource-intents/'+ref.id+'/fulfill'+(mode==='query'?'?extra=1':''),headers,payload});const wanted={query:[400,'INPUT_INVALID'],csrf:[403,'CSRF_INVALID'],connector:[403,'CONNECTOR_CREDENTIAL_SCOPE_DENIED'],'body-limit':[413,'PAYLOAD_TOO_LARGE']} as const;intentError(r,wanted[mode][0],wanted[mode][1]);assert.equal(r.headers['cache-control'],'no-store');assert.equal(f.probe.trace.length,0);assert.equal(f.tables.intents[0].state,'READY');assert.equal(f.resources.versions.length,0);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

for(const failure of ['remove','parent'] as const)test('targetCleanup '+failure+'실패는UNKNOWN·descriptor성공0·자동재probe0이다',async()=>{const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;if(failure==='remove')f.probe.removeFailure=true;else f.probe.parentFailure=true;intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.equal(f.probe.trace.filter(v=>v==='REMOVE').length,1);if(failure==='parent')assert.equal(f.probe.trace.filter(v=>v==='PARENT_SYNC').length,1);else assert.equal(f.probe.files.size,1,'삭제불명 자기검증파일보존');assert.equal(f.resources.versions.length,0);assert.equal(f.tables.intents[0].state,'UNKNOWN');const before=f.probe.trace.length;targetView(await targetGet(f,'/backup-resource-intents/'+ref.id),ref,'UNKNOWN');intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.probe.trace.length,before);assert.equal(f.tables.consumptions.length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});
test('targetReference 등록descriptor의정확ref만기존R2 TARGET명시저장에소비하고receipt/원승인귀속을보존한다',async()=>{const f=await intentFixture({withTargetReference:true});try{const intentRef=intentOk(await f.post(f.command)).data.intentRef,done=targetView(await targetPost(f,intentRef),intentRef,'SUCCEEDED'),snapshot={kind:'TARGET',displayName:'명시 선택한 설치 대상',spec:{installationResourceRef:done.resultRef},reason:'현재 보호조회 뒤 명시 등록'};const command={schemaVersion:1,projectId:pid,commandId:intentId(100),clientId,controlGeneration:1,operation:'saveBackupReference',targetId:null,expectedVersion:0,baselineRefs:[],approvalRef:null,payload:snapshot};const stored=await f.post(command);assert.equal(stored.statusCode,200,stored.body);const result=stored.json();assert.equal(result.data.status,'REFERENCE_STORED');const fixed=await targetGet(f,'/backup-references/'+result.data.ref.id+'/versions/1');assert.equal(fixed.statusCode,200,fixed.body);assert.deepEqual(fixed.json().snapshot,snapshot);assert.equal(fixed.json().current.eligible,true);assert.deepEqual(fixed.json().current.reasonCodes,[]);assert.equal(f.tables.commands.length,2);assert.equal(f.tables.receipts.length,2);assert.equal(f.tables.audits.length,2);assert.equal(f.tables.consumptions.length,1,'TARGET참조AUTO는원manage승인재소비0');assert.equal(f.references.versions.length,1);const body=f.tables.commands.find(c=>c.command_id===command.commandId);assert.equal(body.request_hash,intentHash(command));assert.equal(body.approval_consumption_id,null);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetRace claim COMMIT완료와반환사이같은storeGET은PROCESSING을coldUNKNOWN으로오인하지않는다',async()=>{const f=await intentFixture();let release:(()=>void)|undefined;try{const ref=intentOk(await f.post(f.command)).data.intentRef,original=f.access.authenticated;let entered!:()=>void;const ready=new Promise<void>(r=>entered=r);let armed=true;f.access.authenticated=async(...args:any[])=>{const out=await original(...args);if(armed&&f.tables.intents[0]?.state==='PROCESSING'){armed=false;entered();await new Promise<void>(r=>release=r);}return out;};const pending=targetPost(f,ref);const race=await Promise.race([ready.then(()=>true),Promise.resolve(pending).then(()=>false)]);assert.equal(race,true);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,0,'claim COMMIT반환확인전I/O0');targetView(await targetGet(f,'/backup-resource-intents/'+ref.id),ref,'PROCESSING');release!();targetView(await pending,ref,'SUCCEEDED');assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,1);assert.deepEqual(f.unexpected,[]);}finally{release?.();await f.close();}});
test('targetRoot 다른slot이라도이미귀속된동일device/inode는두번째descriptor로등록하지않는다',async()=>{const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef;f.resources.heads.push({project_id:pid,id:intentId(88),kind:'TARGET',head_version:1,installation_id:intentId(18),slot_id:intentId(89)});f.resources.versions.push({project_id:pid,resource_id:intentId(88),version:1,probe_json:{rootIdentity:{device:'41',inode:'42'}}});intentError(await targetPost(f,ref),409,'RESOURCE_VERSION_CONFLICT');assert.equal(f.resources.heads.length,1);assert.equal(f.resources.versions.length,1);assert.notEqual(f.tables.intents[0].state,'SUCCEEDED');assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetSlots 채택GET경로의닫힌DTO는내부handle/path를투영하지않고옛오타경로는없다',async()=>{const f=await intentFixture();try{const original=f.access.installationResourceCatalog.list;f.access.installationResourceCatalog.list=(kind:string)=>{const v=original(kind);return{...v,items:v.items.map((i:any)=>({...i,absoluteRoot:'/synthetic/private',rootHandle:{},installationId:intentId(18)}))};};const response=await targetGet(f,'/backup-installation-slots?kind=TARGET');assert.equal(response.statusCode,200,response.body);const body=response.json();assert.deepEqual(Object.keys(body).sort(),['items','observedAt','state']);assert.equal(body.state,'CONFIGURED');assert.equal(body.items.length,1);assert.deepEqual(Object.keys(body.items[0]).sort(),['displayName','profileRef','purpose','reasonCodes','slotId','state']);assert.equal(body.items[0].slotId,f.payload.slotId);assert.equal(body.items[0].purpose,'BACKUP_TARGET');assert.equal((await targetGet(f,'/backup-resource-slots?kind=TARGET')).statusCode,404);assert.equal(f.probe.trace.length,0);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetReference 마지막version저장뒤root보호회수는신규reference receipt까지rollback한다',async()=>{const f=await intentFixture({withTargetReference:true});try{const ref=intentOk(await f.post(f.command)).data.intentRef,done=targetView(await targetPost(f,ref),ref,'SUCCEEDED'),original=f.access.authenticated;let hits=0;f.access.authenticated=(token:string,csrf:string|null,body:Function)=>original(token,csrf,async(db:any,a:any)=>body({query:async(sql:string,args:any[])=>{const result=await db.query(sql,args);if(sql.startsWith('INSERT INTO anvil.backup_reference_versions')){hits++;f.probe.rootMode='755';}return result;}},a));const command={schemaVersion:1,projectId:pid,commandId:intentId(101),clientId,controlGeneration:1,operation:'saveBackupReference',targetId:null,expectedVersion:0,baselineRefs:[],approvalRef:null,payload:{kind:'TARGET',displayName:'늦은 보호변경',spec:{installationResourceRef:done.resultRef},reason:'최종 검사'}};intentError(await f.post(command),412,'BACKUP_RESOURCE_PROVIDER_NOT_CONNECTED');assert.equal(hits,1);assert.equal(f.references.versions.length,0);assert.equal(f.tables.commands.length,1);assert.equal(f.tables.receipts.length,1);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});
for(const path of ['slots','intent'] as const)test('targetRead '+path+' 조회중session기한경과는GET200으로반환하지않는다',async()=>{const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef,original=f.access.authenticated;let hits=0;f.access.authenticated=(token:string,csrf:string|null,body:Function)=>original(token,csrf,(db:any,a:any)=>{a.authSession.idleExpiresAt=new Date(Date.parse(f.at)+1000).toISOString();return body({query:async(sql:string,args:any[])=>{const result=await db.query(sql,args);if(path==='intent'&&sql.startsWith('SELECT * FROM anvil.installation_resource_intents')&&hits++===0)f.clock(new Date(Date.parse(f.at)+1001).toISOString());return result;}},a);});if(path==='slots'){const list=f.access.installationResourceCatalog.list;f.access.installationResourceCatalog.list=(kind:string)=>{const result=list(kind);hits++;f.clock(new Date(Date.parse(f.at)+1001).toISOString());return result;};}intentError(await targetGet(f,path==='slots'?'/backup-installation-slots?kind=TARGET':'/backup-resource-intents/'+ref.id),401,'AUTH_REQUIRED');assert(hits>0);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,0);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetPage 보호목록limit와서명cursor는정렬/hasMore/조건격리를유지한다',async()=>{const f=await intentFixture();try{const {BackupReferenceStore}=await import('../../../apps/server/modules/backups/backup-reference-store.ts');const items=[1,2,3].map(n=>({ref:{id:intentId(200+n),version:1,contentHash:String(n).repeat(64)},kind:'TARGET',displayName:'고정 페이지 '+n,verifiedAt:new Date(Date.parse(f.at)+n).toISOString(),current:{eligible:false,reasonCodes:['RESOURCE_PROVIDER_NOT_CONNECTED'],observedAt:f.at}}));let lists=0;const store=new BackupReferenceStore(f.access,{state:'CONFIGURED',list(_pid:string,kind:string,context:any){assert.equal(_pid,pid);assert.equal(kind,'TARGET');assert.equal(context.actor.actorId,actorId);lists++;return items;},read(){return null;}});const first=await store.resources(intentToken,pid,{kind:'TARGET',limit:'1'});assert.deepEqual(first.page.items,[items[2]]);assert.equal(first.page.hasMore,true);assert.equal(typeof first.page.nextCursor,'string');const second=await store.resources(intentToken,pid,{kind:'TARGET',limit:'1',cursor:first.page.nextCursor});assert.deepEqual(second.page.items,[items[1]]);assert.equal(second.page.hasMore,true);const last=await store.resources(intentToken,pid,{kind:'TARGET',limit:'1',cursor:second.page.nextCursor});assert.deepEqual(last.page.items,[items[0]]);assert.equal(last.page.hasMore,false);assert.equal(last.page.nextCursor,null);await assert.rejects(store.resources(intentToken,pid,{kind:'TARGET',limit:'2',cursor:first.page.nextCursor}),exact('CURSOR_INVALID',400));await assert.rejects(store.resources(intentToken,pid,{kind:'ENCRYPTION_KEY',limit:'1',cursor:first.page.nextCursor}),exact('CURSOR_INVALID',400));assert.equal(lists,3,'조건거절은provider조회전');assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});
test('targetRead COMMIT후반환지연도최초session유효창을연장하지않는다',async()=>{const f=await intentFixture();try{const original=f.access.authenticated;let returned=0;f.access.authenticated=async(token:string,csrf:string|null,body:Function)=>{const out=await original(token,csrf,(db:any,a:any)=>{a.authSession.idleExpiresAt=new Date(Date.parse(f.at)+200).toISOString();return body(db,a);});returned++;await new Promise(r=>setTimeout(r,250));return out;};intentError(await targetGet(f,'/backup-installation-slots?kind=TARGET'),401,'AUTH_REQUIRED');assert.equal(returned,1);assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,0);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetGlobalRoot 두OWNER project의동일installation/root는두번째등록409·원descriptor보존이다',async()=>{const shared={heads:[] as any[],versions:[] as any[],events:[] as any[]},a=await intentFixture({sharedResources:shared,globalRootUnique:true}),b=await intentFixture({projectId:intentId(301),sharedResources:shared,globalRootUnique:true});try{const ar=intentOk(await a.post(a.command)).data.intentRef;targetView(await targetPost(a,ar),ar,'SUCCEEDED');const br=intentOk(await b.post(b.command)).data.intentRef;intentError(await targetPost(b,br),409,'RESOURCE_VERSION_CONFLICT');assert.equal(b.fault.hits,1,'전역UNIQUE오류정확도달');assert.equal(shared.heads.length,1);assert.equal(shared.versions.length,1);assert.equal(shared.heads[0].project_id,pid);assert.notEqual(b.tables.intents[0].state,'SUCCEEDED');const list=await targetGet(b,'/backup-resources?kind=TARGET&limit=50');assert.equal(list.statusCode,200,list.body);assert.deepEqual(list.json().page.items,[],'타project자료노출0');assert.deepEqual(a.unexpected,[]);assert.deepEqual(b.unexpected,[]);}finally{await a.close();await b.close();}});
test('targetFinalRoot descriptor INSERT대기중동일handle mode변조는최종성공0·재probe0이다',async()=>{const f=await intentFixture();try{const ref=intentOk(await f.post(f.command)).data.intentRef,original=f.access.authenticated;let hits=0;f.access.authenticated=(token:string,csrf:string|null,body:Function)=>original(token,csrf,(db:any,a:any)=>body({query:async(sql:string,args:any[])=>{const out=await db.query(sql,args);if(sql.startsWith('INSERT INTO anvil.installation_resource_versions')){hits++;f.probe.rootMode='755';}return out;}},a));intentError(await targetPost(f,ref),412,'RESOURCE_UNVERIFIED');assert.equal(hits,1);assert.equal(f.resources.heads.length,0);assert.equal(f.resources.versions.length,0);assert.notEqual(f.tables.intents[0].state,'READY');const before=f.probe.trace.length;intentError(await targetPost(f,ref),412,'RESOURCE_UNVERIFIED');assert.equal(f.probe.trace.length,before);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});
test('targetClaimRollback claimCOMMIT전확정실패도process감사guard아래첫intent를READY로되살리지않는다',async()=>{const f=await intentFixture({eventProcessGuard:true});try{const ref=intentOk(await f.post(f.command)).data.intentRef;f.fault.mode='COMMIT_BEFORE';intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');f.fault.mode='';assert.equal(f.probe.trace.filter(v=>v==='CREATE').length,0);assert.equal(f.tables.intents[0].state,'UNKNOWN');assert.equal(typeof f.tables.intents[0].process_id,'string');const events=f.resources.events.filter(e=>e.intent_id===ref.id);assert.equal(events.filter(e=>e.event_kind==='CLAIMED').length,0,'미확정claim성공이력합성0');assert(events.some(e=>e.event_kind==='UNKNOWN'&&e.process_id===f.tables.intents[0].process_id&&e.snapshot_json.previousState==='READY'&&e.snapshot_json.claimConfirmed===false));const before=f.probe.trace.length;intentError(await targetPost(f,ref),503,'RESOURCE_STATE_UNKNOWN');assert.equal(f.probe.trace.length,before);assert.deepEqual(f.unexpected,[]);}finally{await f.close();}});

test('targetSQLGlobalRoot 미적용0054 전역rootUNIQUE는project를분리키로쓰지않고installation/root에결박한다',async()=>{const {readFile}=await import('node:fs/promises'),sql=await readFile(new URL('../../../db/migrations/0054_backup_installation_resources.sql.pending',import.meta.url),'utf8'),index=/CREATE UNIQUE INDEX installation_resource_root_unique[^;]+;/.exec(sql)?.[0];assert(index);assert.doesNotMatch(index,/\bproject_id\b/,'project한정UNIQUE는전역배타가아님');assert.match(index,/installationId|installation_id/);assert.match(index,/rootIdentity/);assert.match(index,/device/);assert.match(index,/inode/);});
test('targetSQLReadyReduction 미적용0054는미확정READY감소를CLAIMED이력합성없이process귀속으로구분한다',async()=>{const {readFile}=await import('node:fs/promises'),sql=await readFile(new URL('../../../db/migrations/0054_backup_installation_resources.sql.pending',import.meta.url),'utf8');for(const name of ['fn16_installation_write','fn16_installation_complete']){const body=new RegExp('CREATE FUNCTION anvil.'+name+'\\(\\)[\\s\\S]*?END;\\$\\$;').exec(sql)?.[0];assert(body,name+'실함수');assert.match(body,/READY/);assert.match(body,/UNKNOWN/);assert.match(body,/process_id/);}assert.match(sql,/previousState/);assert.match(sql,/claimConfirmed/);assert.match(sql,/INSTALLATION_EVENT_ORIGIN_REQUIRED/);});
